        // header row
        if (!list.isEmpty()) {
            writer.writeRow(list.get(0).keySet());
        }
        for (Map<String, Object> map : list) {
            List<String> row = new ArrayList(map.size());
            for (Object value : map.values()) {
                row.add(value == null ? null : value.toString());
            }
            writer.writeRow(row);
        }
        return sw.toString();
